		Size.Width = 1.0f;
		TopEdgeWidth = 1.0f;
	}

	const f32 extent = 0.5f * sqrtf(Size.Width * Size.Width + Size.Height * Size.Height);
	BBoxSafe.MinEdge.set(-extent, -extent, -extent);
	BBoxSafe.MaxEdge.set(extent, extent, extent);
}

